+    let handoff: CoordinatorHandoffView = rpc_call!(
+        client,
+        FrontendRequest::SetCoordinatorHandoff { body },
+        "handoff write",
+        FrontendEvent::CoordinatorHandoffSet { handoff } => handoff,
+    )?;
