            run_comment_command(command, &ctx).await
        }
        Commands::Decision { command } => {
            let ctx = RunContext::from_flags(&cli.global)?;
            run_decision_command(command, &ctx).await
        }
        Commands::Automation { command } => {
            let ctx = RunContext::from_flags(&cli.global)?;
