    FrontendEventEnvelope::push(FrontendEvent::EngineRequest {
        request_id: request_id.to_owned(),
        request: EngineToAppRequest::ReleaseWorkerPane(ReleaseWorkerPaneInput {
            slot_id: 1,
            kill_grace_seconds: 5,
