        | FrontendRequest::GetDispatchState
        | FrontendRequest::GetEngineHealth
        | FrontendRequest::GetSelectedProduct
        | FrontendRequest::GetSettings
        | FrontendRequest::GetTaskRuntime { .. }
        | FrontendRequest::InterruptWorkerPane { .. }
