fn every_run_carrying_event_is_sanitized() {
    for event in [
        FrontendEvent::RunResult { run: run() },
        FrontendEvent::RunCreated { run: run() },
        FrontendEvent::RunsList {
            execution_id: "exec_1".into(),
            runs: vec![run(), run()],
        },
    ] {
        assert_nothing_leaked(&sanitize_event_for_worker(event));
    }
}

#[test]
fn execution_rows_carry_no_runtime_half_fields() {
    // Today this passes because `WorkExecution` never had `host_id` /
    // `remote_pid` / `shell_pid` on the wire — they are DB columns
    // `mappers.rs` does not map. The assertion is here so that stays true:
    // adding one of them to the struct fails this test until `sanitize.rs`
    // strips it.
    for event in [
        FrontendEvent::ExecutionResult { execution: execution() },
        FrontendEvent::ExecutionsList {
            work_item_id: Some("chore_1".into()),
            executions: vec![execution()],
        },
        FrontendEvent::ExecutionCreated { execution: execution() },
        FrontendEvent::ExecutionRequested { execution: execution() },
        FrontendEvent::ExecutionCancelled { execution: execution() },
        FrontendEvent::RunReaped {
            run_id: "run_1".into(),
            execution: execution(),
        },
        FrontendEvent::PrReviewTriggered {
            execution: execution(),
            work_item_id: "chore_1".into(),
            pr_url: "https://github.com/o/r/pull/1".into(),
        },
    ] {
        assert_nothing_leaked(&sanitize_event_for_worker(event));
    }
}

fn worker_context_bundle() -> WorkerContextBundle {
    WorkerContextBundle {
        task: Task::builder()
            .id("task_1")
            .product_id("prod_1")
            .created_at("1700000000")
            .description("Do a thing")
            .kind(TaskKind::Task)
            .name("A task")
            .status(TaskStatus::Todo)
            .updated_at("1700000000")
            .build(),
        project: None,
        product: Product::builder()
            .id("prod_1")
            .created_at("1700000000")
            .description("A product")
            .name("Widgets")
            .slug("widgets")
            .status("active")
            .updated_at("1700000000")
            .build(),
        sibling_tasks: vec![],
        own_dependencies: WorkItemDependencyDetail {
            work_item_id: "task_1".into(),
            dependents: vec![],
            prerequisites: vec![],
        },
        attention_groups: vec![],
        proposals: vec![],
    }
}

/// `boss context`'s bundle carries no `WorkExecution`/`WorkRun` rows, so it
/// has nothing to strip — but it still has to be a deliberate, named
/// pass-through in `sanitize_event_for_worker`'s exhaustive match (a
/// compile error otherwise), and this pins that it stays leak-free even so.
#[test]
fn worker_context_result_carries_no_runtime_half_fields() {
    let event = FrontendEvent::WorkerContextResult {
        bundle: Box::new(worker_context_bundle()),
    };
    assert_nothing_leaked(&sanitize_event_for_worker(event));
}

/// `boss pr status` / `boss pr body` carry no `WorkExecution`/`WorkRun`
/// rows either — same reasoning as `worker_context_result_carries_no_runtime_half_fields`.
#[test]
fn pr_status_and_pr_body_results_carry_no_runtime_half_fields() {
    let status_event = FrontendEvent::PrStatusResult {
        status: boss_protocol::PrStatusView::builder()
            .pr_url("https://github.com/o/r/pull/1")
            .mergeable("mergeable")
            .build(),
    };
    assert_nothing_leaked(&sanitize_event_for_worker(status_event));

    let body_event = FrontendEvent::PrBodyResult {
        body: boss_protocol::PrBodyView::builder()
            .pr_url("https://github.com/o/r/pull/1")
            .body("## Summary\n...")
            .build(),
    };
    assert_nothing_leaked(&sanitize_event_for_worker(body_event));
}

#[test]
fn unrelated_events_pass_through_untouched() {
    let before = FrontendEvent::ProductsList { products: vec![] };
    let after = sanitize_event_for_worker(before);
    assert!(matches!(after, FrontendEvent::ProductsList { .. }));
}

