    /// `observed_sha` is advisory only — the verdict always re-derives
    /// from the live head SHA. `reason` is free-form (default `already_green`).
    MarkCiRemediationNoop {
        attempt_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
