    ///
    /// Replies with [`FrontendEvent::PrStatusResult`], or
    /// [`FrontendEvent::ProposalRejected`] when attribution fails.
    GetPrStatus {
        run_id: String,
        #[serde(default)]
        refresh: bool,
    },

    GetRun {
        id: String,
    },

