    /// CLI surfaces this as a non-zero exit so the receipt is an
    /// honest pass/fail.
    CiRemediationNoopRejected {
        attempt_id: String,
        work_item_id: String,
        pr_url: String,
        status: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        live_sha: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        observed_sha: Option<String>,
